    windows = await asyncio.to_thread(_selfedit.windows_snapshot, limit)
    log_action(agent_id, 'selfedit_status',
               {'limit': limit, 'windows': len(windows)},
               authorized=authorized)
    return JSONResponse({'edits': edits, 'windows': windows})


